-- Set isolation level for a session
SET TRANSACTION ISOLATION LEVEL READ COMMITTED;  -- default
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;

-- Query hint for dirty reads (READ UNCOMMITTED)
SELECT * FROM orders WITH (NOLOCK);  -- may read uncommitted rows

-- Enable RCSI at database level (best practice for OLTP)
ALTER DATABASE YourDB SET READ_COMMITTED_SNAPSHOT ON;
-- Now all READ COMMITTED queries use row versioning, readers don't block

-- Enable SNAPSHOT isolation
ALTER DATABASE YourDB SET ALLOW_SNAPSHOT_ISOLATION ON;
-- In a session:
SET TRANSACTION ISOLATION LEVEL SNAPSHOT;

-- Explicit transaction
BEGIN TRANSACTION;
  UPDATE accounts SET balance = balance - 100 WHERE id = 1;
  UPDATE accounts SET balance = balance + 100 WHERE id = 2;
  IF @@ERROR != 0 ROLLBACK TRANSACTION
  ELSE COMMIT TRANSACTION;

-- Better: TRY/CATCH for transactions
BEGIN TRY
  BEGIN TRANSACTION;
    UPDATE accounts SET balance = balance - 100 WHERE id = 1;
    UPDATE accounts SET balance = balance + 100 WHERE id = 2;
  COMMIT TRANSACTION;
END TRY
BEGIN CATCH
  IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
  -- Re-raise or log the error
  THROW;
END CATCH;

-- View current locks
SELECT request_session_id, resource_type, resource_description,
       request_mode, request_status
FROM sys.dm_tran_locks WHERE resource_database_id = DB_ID();
